const c06_timeline_namespaceObject = /*#__PURE__*/JSON.parse('{"slug":"iphone-1926/c06","title":" ","fps":30,"total":2285,"segments":[{"shot":"S1","a":0,"b":62,"t0":0,"t1":62,"line":"A week later, Ellie gets sick."},{"shot":"S2","a":62,"b":116,"t0":0,"t1":54,"line":"A cut on her knee from the street."},{"shot":"S4","a":116,"b":149,"t0":0,"t1":33,"line":"Then a fever."},{"shot":"S3","a":149,"b":216,"t0":0,"t1":67,"line":"Then red lines creeping up her leg."},{"shot":"S5","a":216,"b":359,"t0":0,"t1":143,"line":"The doctor comes. He\'s kind, and he\'s honest. There\'s nothing he can give her."},{"shot":"S4","a":359,"b":446,"t0":0,"t1":87,"line":"Mo\'s mom sits by the bed all night with a wet cloth."},{"shot":"S6","a":446,"b":504,"t0":0,"t1":58,"line":"Mo tries to make Ellie laugh."},{"shot":"S7","a":504,"b":627,"t0":0,"t1":123,"line":"She asks for the star. You turn on the flashlight, and she smiles."},{"shot":"S8","a":627,"b":683,"t0":0,"t1":56,"line":"Somehow, that\'s worse."},{"shot":"S9","a":683,"b":926,"t0":0,"t1":243,"line":"Antibiotics don\'t exist yet. Penicillin won\'t be discovered until September 1928, almost two years from now. That\'s real."},{"shot":"S11","a":926,"b":992,"t0":0,"t1":66,"line":"You know exactly what penicillin is."},{"shot":"S10","a":992,"b":1067,"t0":0,"t1":75,"line":"You even have a photo of a pharmacy shelf full of it."},{"shot":"S11","a":1067,"b":1183,"t0":0,"t1":116,"line":"But a photo can\'t cure anyone. You need someone who can make it."},{"shot":"S12","a":1183,"b":1419,"t0":0,"t1":236,"line":"That night, the man in the grey suit comes back. He doesn\'t bring money this time. He brings a laboratory. Chemists. Equipment."},{"shot":"S13","a":1419,"b":1556,"t0":0,"t1":137,"line":"\'Give us the phone, \' he says, \'and we\'ll make your medicine. Whatever you can show us. \'"},{"shot":"S14","a":1556,"b":1642,"t0":0,"t1":86,"line":"Mo is sitting on the stairs. He heard everything."},{"shot":"S15","a":1642,"b":1710,"t0":0,"t1":68,"line":"Ellie is asleep upstairs, burning hot."},{"shot":"S16","a":1710,"b":1974,"t0":0,"t1":264,"line":"Give it away, and the future changes. Maybe millions of people you\'ll never meet live, or don\'t. Keep it, and a little girl might never see 1927."},{"shot":"S17","a":1974,"b":2127,"t0":0,"t1":153,"line":"You think about every time travel movie you\'ve ever seen. Don\'t change anything. Don\'t touch anything."},{"shot":"S18","a":2127,"b":2197,"t0":0,"t1":70,"line":"Easy to say, when it\'s not your family."},{"shot":"S19","a":2197,"b":2285,"t0":0,"t1":88,"line":"You look down at the screen. Nine percent."}],"shots":[{"id":"S1","size":"card","key":20,"len":62,"first":0,"line":"A week later, Ellie gets sick.","note":"CHAPTER 6: THE CHOICE"},{"id":"S2","size":"wide","key":20,"len":54,"first":62,"line":"A cut on her knee from the street.","note":"Ellie trips and cuts her knee"},{"id":"S4","size":"top","key":20,"len":87,"first":116,"line":"Then a fever.","note":"Ellie in bed with a fever"},{"id":"S3","size":"insert","key":20,"len":67,"first":149,"line":"Then red lines creeping up her leg.","note":"red lines creeping up her leg"},{"id":"S5","size":"medium","key":20,"len":143,"first":216,"line":"The doctor comes. He\'s kind, and he\'s honest. There\'s nothing he can give her.","note":"the doctor can\'t help"},{"id":"S6","size":"close","key":20,"len":58,"first":446,"line":"Mo tries to make Ellie laugh.","note":"Mo pulls faces for Ellie"},{"id":"S7","size":"top","key":20,"len":123,"first":504,"line":"She asks for the star. You turn on the flashlight, and she smiles.","note":"the flashlight star again"},{"id":"S8","size":"close","key":20,"len":56,"first":627,"line":"Somehow, that\'s worse.","note":"your face: somehow that\'s worse"},{"id":"S9","size":"card","key":90,"len":243,"first":683,"line":"Antibiotics don\'t exist yet. Penicillin won\'t be discovered until September 1928, almost two years from now. That\'s real.","note":"fact: penicillin, September 1928"},{"id":"S11","size":"close","key":20,"len":116,"first":926,"line":"You know exactly what penicillin is.","note":"a photo can\'t cure anyone"},{"id":"S10","size":"insert","key":20,"len":75,"first":992,"line":"You even have a photo of a pharmacy shelf full of it.","note":"a photo of a pharmacy shelf"},{"id":"S12","size":"medium","key":20,"len":236,"first":1183,"line":"That night, the man in the grey suit comes back. He doesn\'t bring money this time. He brings a laboratory. Chemists. Equipment.","note":"the grey suit returns with a laboratory"},{"id":"S13","size":"two-shot","key":20,"len":137,"first":1419,"line":"\'Give us the phone, \' he says, \'and we\'ll make your medicine. Whatever you can show us. \'","note":"give us the phone"},{"id":"S14","size":"medium","key":20,"len":86,"first":1556,"line":"Mo is sitting on the stairs. He heard everything.","note":"Mo on the stairs heard everything"},{"id":"S15","size":"top","key":20,"len":68,"first":1642,"line":"Ellie is asleep upstairs, burning hot.","note":"Ellie asleep, burning hot"},{"id":"S16","size":"card","key":90,"len":264,"first":1710,"line":"Give it away, and the future changes. Maybe millions of people you\'ll never meet live, or don\'t. Keep it, and a little girl might never see 1927.","note":"the scales: the world against one girl"},{"id":"S17","size":"card","key":90,"len":153,"first":1974,"line":"You think about every time travel movie you\'ve ever seen. Don\'t change anything. Don\'t touch anything.","note":"don\'t change anything"},{"id":"S18","size":"medium","key":20,"len":70,"first":2127,"line":"Easy to say, when it\'s not your family.","note":"you on the bottom step"},{"id":"S19","size":"insert","key":20,"len":88,"first":2197,"line":"You look down at the screen. Nine percent.","note":"nine percent"}],"fx":[],"audio":{"voice":"iphone-1926/c06/voice.wav","sfx":"iphone-1926/c06/sfx.wav","voiceVol":0.8,"sfxVol":0.499,"music":"iphone-1926/c06/music.wav","musicVol":0.0721}}');
